mapper.insert:
		INSERT /* SQL_ID: CodeMapper.insertCode */
		       INTO dtmeta.tb_portal_code
			 ( mtcd_grp_id	
			 , mtcd	
			 , mtcd_nm	
			 , mtcd_use_yn	
			 , mtcd_sort_odrg	
			 , mtcd_desc	
			 , up_mtcd	
			 , mtcd_regr_id	
			 , mtcd_regr_nm	
			 , mtcd_reg_dt		 
			 , mtcd_amdr_id
             , mtcd_amdr_nm
             , mtcd_amd_dt
			 ) VALUES 
			 ( #{mtcdGrpId}
			 , #{mtcd}
			 , #{mtcdNm}
			 , #{mtcdUseYn}
			 , #{mtcdSortOdrg}
			 , #{mtcdDesc}
			 , #{upMtcd}
			 , #{mtcdRegrId}
			 , #{mtcdRegrNm}
			 , current_timestamp 
			 , #{mtcdAmdrId}
			 , #{mtcdAmdrNm}
			 , current_timestamp
			 )

mapper.update:
		UPDATE /* SQL_ID: CodeMapper.updateCode */
               dtmeta.tb_portal_code
		   SET mtcd_nm 			= #{mtcdNm}
             , mtcd_use_yn 		= #{mtcdUseYn}
             , mtcd_sort_odrg 	= #{mtcdSortOdrg}			 
			 , mtcd_desc 		= #{mtcdDesc}
			 , up_mtcd 			= #{upMtcd}
             , mtcd_amdr_id 	= #{mtcdAmdrId}
             , mtcd_amdr_nm 	= #{mtcdAmdrNm}
             , mtcd_amd_dt 		= current_timestamp
		 WHERE mtcd_grp_id 	    = #{mtcdGrpId}
		   AND mtcd 		    = #{mtcd}

mapper.select:
SELECT EXISTS (
	SELECT 1
	FROM dtmeta.tb_portal_code
	WHERE mtcd = #{mtcd}
	AND mtcd_grp_id = #{mtcdGrpId}
)
